use anyhow::{Context, Result};
use std::fs;
use std::path::PathBuf;

pub fn generate_wrangler_toml(build_dir: &PathBuf) -> Result<PathBuf> {
    let wrangler_path = build_dir.join("wrangler.toml");

    // Minimal wrangler.toml for local development
    // This allows wrangler dev to work without needing Cloudflare account configuration
    let wrangler_config = r#"# Wrangler configuration for Whippy custom integrations
# This file is auto-generated by whippy-workflows-cli build

name = "whippy-integration"
main = "index.js"
compatibility_date = "2024-09-23"
compatibility_flags = ["nodejs_compat"]

# Increase CPU time limit to 5 minutes (requires Workers Paid plan)
[limits]
cpu_ms = 300000

# Local development settings
[dev]
port = 8787
"#;

    fs::write(&wrangler_path, wrangler_config)
        .with_context(|| format!("Failed to write wrangler.toml: {}", wrangler_path.display()))?;

    Ok(wrangler_path)
}
